        ("«".to_owned(), "»".to_owned()),
        (quote.clone(), quote.clone()),
        (
            format!("{}text\n", quote.repeat(4)),
            format!("\n{}", quote.repeat(4)),
        ),
        (
            format!("{}text\n", quote.repeat(12)),
            format!("\n{}", quote.repeat(12)),
        ),
    ];
